-- NEXORA FORGE ACADEMY INSTALL — PART 14/21
-- Curriculum lessons 199-216 of 324

begin;
insert into public.academy_lessons(id,course_id,title,slug,summary,content_html,starter_code,exercise,status,sort_order,estimated_minutes)
select x.id,c.id,x.title,x.slug,x.summary,x.content_html,x.starter_code,x.exercise,x.status,x.sort_order,x.estimated_minutes
from jsonb_to_recordset($lessons$[{"id":"curriculum-324-css-advanced-19","course_id":"css-advanced","title":"قاب‌بندی رسانه با aspect-ratio و object-position","slug":"css-advanced-19","summary":"نسبت تصویر قاب رسانه را پایدار می‌کند و object-position نقطه کانونی برش را کنترل می‌کند.","content_html":"<h3>هدف درس</h3><p>نسبت تصویر قاب رسانه را پایدار می‌کند و object-position نقطه کانونی برش را کنترل می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.cover { aspect-ratio:16/9; overflow:hidden; }\n.cover img { width:100%; height:100%; object-fit:cover; object-position:50% 30%; }\n.avatar { aspect-ratio:1; border-radius:50%; }</code></pre><h3>تمرین عملی</h3><p>سه تصویر با نسبت متفاوت را در کارت قرار بده و نقطه کانونی هرکدام را تنظیم کن.</p><h3>نکته فنی</h3><p>cover بخشی از تصویر را حذف می‌کند؛ برش محتوای معنادار را بررسی کن.</p><h3>معیار موفقیت</h3><p>کارت‌ها هم‌اندازه باشند و سوژه اصلی حفظ شود.</p>","starter_code":".cover { aspect-ratio:16/9; overflow:hidden; }\n.cover img { width:100%; height:100%; object-fit:cover; object-position:50% 30%; }\n.avatar { aspect-ratio:1; border-radius:50%; }","exercise":"سه تصویر با نسبت متفاوت را در کارت قرار بده و نقطه کانونی هرکدام را تنظیم کن.","status":"published","sort_order":19,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-20","course_id":"css-advanced","title":"دسترس‌پذیری رنگ در forced-colors","slug":"css-advanced-20","summary":"در حالت رنگ اجباری سیستم باید از رنگ‌های سیستمی و نشانه‌های غیررنگی استفاده شود.","content_html":"<h3>هدف درس</h3><p>در حالت رنگ اجباری سیستم باید از رنگ‌های سیستمی و نشانه‌های غیررنگی استفاده شود.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.button { border:2px solid transparent; }\n@media (forced-colors:active) { .button { color:ButtonText; background:ButtonFace; border-color:ButtonText; } .selected { outline:2px solid Highlight; } }</code></pre><h3>تمرین عملی</h3><p>فرمی با وضعیت انتخاب و خطا بساز و در حالت forced-colors بررسی کن.</p><h3>نکته فنی</h3><p>با forced-color-adjust بی‌دلیل کنترل رنگ سیستم را خنثی نکن.</p><h3>معیار موفقیت</h3><p>متن، مرز و وضعیت انتخاب در حالت کنتراست اجباری قابل تشخیص باشند.</p>","starter_code":".button { border:2px solid transparent; }\n@media (forced-colors:active) { .button { color:ButtonText; background:ButtonFace; border-color:ButtonText; } .selected { outline:2px solid Highlight; } }","exercise":"فرمی با وضعیت انتخاب و خطا بساز و در حالت forced-colors بررسی کن.","status":"published","sort_order":20,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-21","course_id":"css-advanced","title":"افزایش خوانایی با prefers-contrast","slug":"css-advanced-21","summary":"prefers-contrast ترجیح کنتراست کاربر را گزارش می‌کند و می‌تواند متن و مرزها را تقویت کند.","content_html":"<h3>هدف درس</h3><p>prefers-contrast ترجیح کنتراست کاربر را گزارش می‌کند و می‌تواند متن و مرزها را تقویت کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.card { border:1px solid #9aa4b2; }\n@media (prefers-contrast:more) { .card { border-width:2px; } .muted { color:#263244; } }</code></pre><h3>تمرین عملی</h3><p>برای کارت‌ها و متن کم‌رنگ حالت کنتراست بالا بساز و آزمایش کن.</p><h3>نکته فنی</h3><p>تغییر ظاهری باید خوانایی واقعی را افزایش دهد، نه فقط ضخامت تزئینی را.</p><h3>معیار موفقیت</h3><p>اطلاعات ثانویه نیز در حالت کنتراست بالا خوانا باشند.</p>","starter_code":".card { border:1px solid #9aa4b2; }\n@media (prefers-contrast:more) { .card { border-width:2px; } .muted { color:#263244; } }","exercise":"برای کارت‌ها و متن کم‌رنگ حالت کنتراست بالا بساز و آزمایش کن.","status":"published","sort_order":21,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-22","course_id":"css-advanced","title":"طراحی ورودی چندگانه با pointer و hover","slug":"css-advanced-22","summary":"pointer و hover قابلیت ورودی را گزارش می‌کنند و باید برای بهبود تعامل استفاده شوند.","content_html":"<h3>هدف درس</h3><p>pointer و hover قابلیت ورودی را گزارش می‌کنند و باید برای بهبود تعامل استفاده شوند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.action { min-block-size:2.75rem; }\n@media (hover:hover) and (pointer:fine) { .action:hover { transform:translateY(-1px); } }\n@media (pointer:coarse) { .action { padding-inline:1.1rem; } }</code></pre><h3>تمرین عملی</h3><p>منویی بساز که با لمس، ماوس و صفحه‌کلید کامل کار کند و hover فقط افزوده باشد.</p><h3>نکته فنی</h3><p>دستگاه‌های ترکیبی ممکن است بیش از یک نوع ورودی داشته باشند.</p><h3>معیار موفقیت</h3><p>هیچ عملکرد ضروری فقط با hover در دسترس نباشد.</p>","starter_code":".action { min-block-size:2.75rem; }\n@media (hover:hover) and (pointer:fine) { .action:hover { transform:translateY(-1px); } }\n@media (pointer:coarse) { .action { padding-inline:1.1rem; } }","exercise":"منویی بساز که با لمس، ماوس و صفحه‌کلید کامل کار کند و hover فقط افزوده باشد.","status":"published","sort_order":22,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-23","course_id":"css-advanced","title":"ترکیب چند انیمیشن با animation-composition","slug":"css-advanced-23","summary":"این ویژگی تعیین می‌کند انیمیشن‌های هم‌زمان روی یک ویژگی چگونه ترکیب شوند.","content_html":"<h3>هدف درس</h3><p>این ویژگی تعیین می‌کند انیمیشن‌های هم‌زمان روی یک ویژگی چگونه ترکیب شوند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>@keyframes drift { to { transform:translateX(1rem); } }\n@keyframes pulse { to { transform:scale(1.08); } }\n.icon { animation:drift 2s alternate infinite,pulse 1s alternate infinite; animation-composition:add; }</code></pre><h3>تمرین عملی</h3><p>دو انیمیشن روی transform بساز و رفتار replace و add را مقایسه کن.</p><h3>نکته فنی</h3><p>ترکیب چند transform ممکن است حرکت ناخواسته ایجاد کند؛ نتیجه را اندازه‌گیری کن.</p><h3>معیار موفقیت</h3><p>هر انیمیشن اثر قابل پیش‌بینی داشته باشد و حرکت اضافی کنترل شود.</p>","starter_code":"@keyframes drift { to { transform:translateX(1rem); } }\n@keyframes pulse { to { transform:scale(1.08); } }\n.icon { animation:drift 2s alternate infinite,pulse 1s alternate infinite; animation-composition:add; }","exercise":"دو انیمیشن روی transform بساز و رفتار replace و add را مقایسه کن.","status":"published","sort_order":23,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-24","course_id":"css-advanced","title":"کنترل گذار ویژگی‌های گسسته","slug":"css-advanced-24","summary":"transition-behavior می‌تواند برخی تغییرهای گسسته مانند display را در گذار مشارکت دهد.","content_html":"<h3>هدف درس</h3><p>transition-behavior می‌تواند برخی تغییرهای گسسته مانند display را در گذار مشارکت دهد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.panel { display:none; opacity:0; transition:opacity .2s,display .2s allow-discrete; }\n.panel.open { display:block; opacity:1; }\n@starting-style { .panel.open { opacity:0; } }</code></pre><h3>تمرین عملی</h3><p>پنل بازشو بساز و دسترسی فوکوس و صفحه‌خوان را در حالت بسته بررسی کن.</p><h3>نکته فنی</h3><p>مخفی‌سازی بصری به‌تنهایی برای حذف از ترتیب فوکوس کافی نیست؛ وضعیت تعاملی را نیز مدیریت کن.</p><h3>معیار موفقیت</h3><p>پنل درست باز و بسته شود و محتوای بسته قابل فوکوس نباشد.</p>","starter_code":".panel { display:none; opacity:0; transition:opacity .2s,display .2s allow-discrete; }\n.panel.open { display:block; opacity:1; }\n@starting-style { .panel.open { opacity:0; } }","exercise":"پنل بازشو بساز و دسترسی فوکوس و صفحه‌خوان را در حالت بسته بررسی کن.","status":"published","sort_order":24,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-25","course_id":"css-advanced","title":"انیمیشن سازگار با prefers-reduced-motion","slug":"css-advanced-25","summary":"کاهش حرکت باید افکت‌های غیرضروری را حذف کند و بازخورد وضعیت را نگه دارد.","content_html":"<h3>هدف درس</h3><p>کاهش حرکت باید افکت‌های غیرضروری را حذف کند و بازخورد وضعیت را نگه دارد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.card { transition:transform .25s ease,opacity .25s ease; }\n@media (prefers-reduced-motion:reduce) { .card { transition:opacity .12s linear; } .parallax { transform:none !important; } }</code></pre><h3>تمرین عملی</h3><p>برای صفحه دارای parallax نسخه کاهش حرکت طراحی و با تنظیم سیستم آزمایش کن.</p><h3>نکته فنی</h3><p>خاموش کردن تمام بازخوردها می‌تواند تغییر وضعیت را مبهم کند؛ جایگزین ساده ارائه بده.</p><h3>معیار موفقیت</h3><p>کاربر همچنان تغییر وضعیت را واضح تشخیص دهد.</p>","starter_code":".card { transition:transform .25s ease,opacity .25s ease; }\n@media (prefers-reduced-motion:reduce) { .card { transition:opacity .12s linear; } .parallax { transform:none !important; } }","exercise":"برای صفحه دارای parallax نسخه کاهش حرکت طراحی و با تنظیم سیستم آزمایش کن.","status":"published","sort_order":25,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-26","course_id":"css-advanced","title":"شکست خطوط هوشمند با text-wrap","slug":"css-advanced-26","summary":"text-wrap balance و pretty شکست خطوط را برای تیتر و بدنه بهبود می‌دهند؛ hyphenation باید زبان‌محور باشد.","content_html":"<h3>هدف درس</h3><p>text-wrap balance و pretty شکست خطوط را برای تیتر و بدنه بهبود می‌دهند؛ hyphenation باید زبان‌محور باشد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.article-title { text-wrap:balance; }\n.article-body { text-wrap:pretty; hyphens:auto; }\n[lang=\"fa\"] { hyphens:manual; }</code></pre><h3>تمرین عملی</h3><p>تیتر و پاراگراف فارسی و انگلیسی را در چند عرض آزمایش کن.</p><h3>نکته فنی</h3><p>کیفیت hyphenation میان زبان‌ها متفاوت است؛ برای فارسی خط تیره خودکار را بدون آزمون فعال نکن.</p><h3>معیار موفقیت</h3><p>تیتر متوازن و پاراگراف بدون شکست عجیب نمایش داده شود.</p>","starter_code":".article-title { text-wrap:balance; }\n.article-body { text-wrap:pretty; hyphens:auto; }\n[lang=\"fa\"] { hyphens:manual; }","exercise":"تیتر و پاراگراف فارسی و انگلیسی را در چند عرض آزمایش کن.","status":"published","sort_order":26,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-27","course_id":"css-advanced","title":"تنظیم ویژگی‌های OpenType برای داده و کد","slug":"css-advanced-27","summary":"ویژگی‌های قلم مانند kerning و اعداد جدولی می‌توانند تراز داده‌ها و خوانایی کد را بهبود دهند.","content_html":"<h3>هدف درس</h3><p>ویژگی‌های قلم مانند kerning و اعداد جدولی می‌توانند تراز داده‌ها و خوانایی کد را بهبود دهند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.data { font-kerning:normal; font-variant-numeric:tabular-nums; }\n.code { font-variant-ligatures:none; }</code></pre><h3>تمرین عملی</h3><p>جدول قیمت و قطعه‌کد بساز؛ اعداد را هم‌تراز و ligature کد را خاموش کن.</p><h3>نکته فنی</h3><p>ابتدا ویژگی‌های سطح بالاتر font-variant را ترجیح بده و تنظیمات سطح پایین را فقط در صورت نیاز به کار ببر.</p><h3>معیار موفقیت</h3><p>اعداد ستون‌ها هم‌تراز و کد بدون اتصال حروف ناخواسته باشد.</p>","starter_code":".data { font-kerning:normal; font-variant-numeric:tabular-nums; }\n.code { font-variant-ligatures:none; }","exercise":"جدول قیمت و قطعه‌کد بساز؛ اعداد را هم‌تراز و ligature کد را خاموش کن.","status":"published","sort_order":27,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-28","course_id":"css-advanced","title":"نوشتار عمودی و نشانه‌گذاری آویخته","slug":"css-advanced-28","summary":"writing-mode و hanging-punctuation برای متن‌های عمودی و نشانه‌گذاری خاص کاربرد دارند.","content_html":"<h3>هدف درس</h3><p>writing-mode و hanging-punctuation برای متن‌های عمودی و نشانه‌گذاری خاص کاربرد دارند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.vertical-label { writing-mode:vertical-rl; text-orientation:mixed; }\n.quote { hanging-punctuation:first; }</code></pre><h3>تمرین عملی</h3><p>برچسب عمودی تزئینی بساز و ترتیب خواندن صفحه را بررسی کن.</p><h3>نکته فنی</h3><p>پشتیبانی ویژگی‌های نشانه‌گذاری میان مرورگرها متفاوت است.</p><h3>معیار موفقیت</h3><p>متن اصلی در ترتیب منطقی بماند و برچسب خوانا باشد.</p>","starter_code":".vertical-label { writing-mode:vertical-rl; text-orientation:mixed; }\n.quote { hanging-punctuation:first; }","exercise":"برچسب عمودی تزئینی بساز و ترتیب خواندن صفحه را بررسی کن.","status":"published","sort_order":28,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-29","course_id":"css-advanced","title":"صفحه‌بندی چاپ با widows و orphans","slug":"css-advanced-29","summary":"قواعد paged media شکست صفحه و خطوط تنها در ابتدا و انتهای صفحه را کنترل می‌کنند.","content_html":"<h3>هدف درس</h3><p>قواعد paged media شکست صفحه و خطوط تنها در ابتدا و انتهای صفحه را کنترل می‌کنند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>@media print { .toolbar { display:none !important; } h2 { break-after:avoid-page; } p { orphans:3; widows:3; } a { color:inherit; text-decoration:underline; } }</code></pre><h3>تمرین عملی</h3><p>گزارش چندصفحه‌ای بساز و تیترهای جداافتاده را در پیش‌نمایش چاپ اصلاح کن.</p><h3>نکته فنی</h3><p>چاپگرها و مرورگرها ممکن است رفتار متفاوتی داشته باشند؛ خروجی واقعی را ببین.</p><h3>معیار موفقیت</h3><p>گزارش بدون ابزارهای تعاملی و با تیترهای همراه محتوا خوانا باشد.</p>","starter_code":"@media print { .toolbar { display:none !important; } h2 { break-after:avoid-page; } p { orphans:3; widows:3; } a { color:inherit; text-decoration:underline; } }","exercise":"گزارش چندصفحه‌ای بساز و تیترهای جداافتاده را در پیش‌نمایش چاپ اصلاح کن.","status":"published","sort_order":29,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-30","course_id":"css-advanced","title":"هماهنگی color-scheme با کنترل‌های بومی","slug":"css-advanced-30","summary":"color-scheme اعلام می‌کند کنترل‌های بومی مرورگر با چه طرح رنگی سازگارند.","content_html":"<h3>هدف درس</h3><p>color-scheme اعلام می‌کند کنترل‌های بومی مرورگر با چه طرح رنگی سازگارند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>:root { color-scheme:light dark; }\n.light { color-scheme:light; }\n.dark { color-scheme:dark; }\ninput,select { accent-color:var(--brand,#2457a6); }</code></pre><h3>تمرین عملی</h3><p>فرم ورود با تم روشن و تاریک بساز و کنترل‌های بومی را در هر دو حالت بررسی کن.</p><h3>نکته فنی</h3><p>اعلام color-scheme به‌تنهایی رنگ‌های سفارشی و کنتراست متن را اصلاح نمی‌کند.</p><h3>معیار موفقیت</h3><p>کنترل‌ها با پس‌زمینه هماهنگ و خوانا باشند.</p>","starter_code":":root { color-scheme:light dark; }\n.light { color-scheme:light; }\n.dark { color-scheme:dark; }\ninput,select { accent-color:var(--brand,#2457a6); }","exercise":"فرم ورود با تم روشن و تاریک بساز و کنترل‌های بومی را در هر دو حالت بررسی کن.","status":"published","sort_order":30,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-31","course_id":"css-advanced","title":"فوکوس چندلایه با focus-visible و focus-within","slug":"css-advanced-31","summary":"این شبه‌کلاس‌ها فوکوس صفحه‌کلید و ظرف دارای عنصر متمرکز را واضح می‌کنند.","content_html":"<h3>هدف درس</h3><p>این شبه‌کلاس‌ها فوکوس صفحه‌کلید و ظرف دارای عنصر متمرکز را واضح می‌کنند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.field:focus-within { border-color:var(--brand); box-shadow:0 0 0 3px #2457a633; }\n:where(button,a,input):focus-visible { outline:3px solid #e08a00; outline-offset:3px; }</code></pre><h3>تمرین عملی</h3><p>فرم بساز و با Tab و ماوس آزمایش کن؛ فوکوس را بدون جایگزین حذف نکن.</p><h3>نکته فنی</h3><p>outline قابل مشاهده برای کاربر صفحه‌کلید ضروری است.</p><h3>معیار موفقیت</h3><p>محل فوکوس در تمام مراحل قابل تشخیص باشد.</p>","starter_code":".field:focus-within { border-color:var(--brand); box-shadow:0 0 0 3px #2457a633; }\n:where(button,a,input):focus-visible { outline:3px solid #e08a00; outline-offset:3px; }","exercise":"فرم بساز و با Tab و ماوس آزمایش کن؛ فوکوس را بدون جایگزین حذف نکن.","status":"published","sort_order":31,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-32","course_id":"css-advanced","title":"مدیریت stacking context در لایه‌ها","slug":"css-advanced-32","summary":"stacking context ترتیب z-index را در محدوده‌های مستقل نگه می‌دارد و برخی ویژگی‌ها آن را ایجاد می‌کنند.","content_html":"<h3>هدف درس</h3><p>stacking context ترتیب z-index را در محدوده‌های مستقل نگه می‌دارد و برخی ویژگی‌ها آن را ایجاد می‌کنند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.app { isolation:isolate; }\n.modal-layer { position:fixed; inset:0; z-index:100; }\n.toast-layer { position:fixed; inset:0; z-index:200; pointer-events:none; }\n.toast { pointer-events:auto; }</code></pre><h3>تمرین عملی</h3><p>modal و toast بساز و دلیل ترتیب نمایش را با بررسی context والد پیدا کن.</p><h3>نکته فنی</h3><p>z-index بسیار بزرگ مشکل context والد را حل نمی‌کند.</p><h3>معیار موفقیت</h3><p>لایه‌ها در ترتیب مورد انتظار باشند و کلیک‌ها درست مدیریت شوند.</p>","starter_code":".app { isolation:isolate; }\n.modal-layer { position:fixed; inset:0; z-index:100; }\n.toast-layer { position:fixed; inset:0; z-index:200; pointer-events:none; }\n.toast { pointer-events:auto; }","exercise":"modal و toast بساز و دلیل ترتیب نمایش را با بررسی context والد پیدا کن.","status":"published","sort_order":32,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-33","course_id":"css-advanced","title":"پیشگیری از جابه‌جایی چیدمان با رزرو فضا","slug":"css-advanced-33","summary":"رزرو ابعاد تصویر و محتوای دیررس از layout shift جلوگیری می‌کند.","content_html":"<h3>هدف درس</h3><p>رزرو ابعاد تصویر و محتوای دیررس از layout shift جلوگیری می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.article-image { display:block; width:100%; aspect-ratio:3/2; object-fit:cover; }\n.ad-slot { min-block-size:18rem; }\n.avatar { width:3rem; aspect-ratio:1; }</code></pre><h3>تمرین عملی</h3><p>صفحه خبری را با و بدون فضای رزروشده بارگذاری و تفاوت جابه‌جایی را مقایسه کن.</p><h3>نکته فنی</h3><p>فضای رزروشده را با اندازه واقعی محتوا هماهنگ کن تا فضای خالی بی‌دلیل نسازی.</p><h3>معیار موفقیت</h3><p>بارگذاری رسانه باعث پرش محسوس متن و کنترل‌ها نشود.</p>","starter_code":".article-image { display:block; width:100%; aspect-ratio:3/2; object-fit:cover; }\n.ad-slot { min-block-size:18rem; }\n.avatar { width:3rem; aspect-ratio:1; }","exercise":"صفحه خبری را با و بدون فضای رزروشده بارگذاری و تفاوت جابه‌جایی را مقایسه کن.","status":"published","sort_order":33,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-34","course_id":"css-advanced","title":"اندازه‌گیری هزینه CSS در DevTools","slug":"css-advanced-34","summary":"بهینه‌سازی CSS باید بر اساس Performance و Coverage باشد، نه باورهای کلی درباره selectorها.","content_html":"<h3>هدف درس</h3><p>بهینه‌سازی CSS باید بر اساس Performance و Coverage باشد، نه باورهای کلی درباره selectorها.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>/* selector آزمایشی برای مقایسه */\n.page .catalog .item .title strong { color:#182230; }\n.catalog-title { color:#182230; }</code></pre><h3>تمرین عملی</h3><p>دو نسخه selector را با داده Performance و Coverage مقایسه و نتیجه را ثبت کن.</p><h3>نکته فنی</h3><p>هزینه واقعی به DOM، تعداد عناصر و دفعات تغییر style وابسته است.</p><h3>معیار موفقیت</h3><p>پیشنهاد بهینه‌سازی با داده قبل و بعد مستند شود.</p>","starter_code":"/* selector آزمایشی برای مقایسه */\n.page .catalog .item .title strong { color:#182230; }\n.catalog-title { color:#182230; }","exercise":"دو نسخه selector را با داده Performance و Coverage مقایسه و نتیجه را ثبت کن.","status":"published","sort_order":34,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-35","course_id":"css-advanced","title":"راهبرد fallback برای قابلیت‌های نوظهور","slug":"css-advanced-35","summary":"نسخه پایه باید مستقل کار کند و قابلیت جدید فقط به‌عنوان ارتقا فعال شود.","content_html":"<h3>هدف درس</h3><p>نسخه پایه باید مستقل کار کند و قابلیت جدید فقط به‌عنوان ارتقا فعال شود.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.panel { display:block; }\n@supports (container-type:inline-size) { .panel { container-type:inline-size; } @container (min-width:36rem) { .panel__body { columns:2; } } }</code></pre><h3>تمرین عملی</h3><p>برای یک ویژگی تازه نسخه پایه، شرط پشتیبانی و روش آزمون مرورگر را مستند کن.</p><h3>نکته فنی</h3><p>@supports پشتیبانی نحوی را می‌سنجد، نه نبود باگ در پیاده‌سازی.</p><h3>معیار موفقیت</h3><p>محتوا در مرورگر قدیمی قابل استفاده و در مرورگر جدید بهبود یافته باشد.</p>","starter_code":".panel { display:block; }\n@supports (container-type:inline-size) { .panel { container-type:inline-size; } @container (min-width:36rem) { .panel__body { columns:2; } } }","exercise":"برای یک ویژگی تازه نسخه پایه، شرط پشتیبانی و روش آزمون مرورگر را مستند کن.","status":"published","sort_order":35,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-36","course_id":"css-advanced","title":"پروژه نهایی: داشبورد تولیدی و واکنش‌گرا","slug":"css-advanced-36","summary":"پروژه نهایی معماری مؤلفه، اندازه‌گذاری پیشرفته، ورودی‌های چندگانه، دسترس‌پذیری و fallback را ترکیب می‌کند.","content_html":"<h3>هدف درس</h3><p>پروژه نهایی معماری مؤلفه، اندازه‌گذاری پیشرفته، ورودی‌های چندگانه، دسترس‌پذیری و fallback را ترکیب می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>@layer reset,tokens,layout,components,utilities;\n@layer tokens { :root { --space:1rem; --surface:#fff; --ink:#182230; --brand:#2457a6; } }\n@layer layout { .dashboard { display:grid; grid-template-columns:16rem minmax(0,1fr); min-block-size:100dvh; } }\n@layer components { .metric { container-type:inline-size; padding:var(--space); background:var(--surface); color:var(--ink); border:1px solid #ccd3dc; border-radius:1rem; } }\n@media (max-width:48rem) { .dashboard { grid-template-columns:1fr; } }</code></pre><h3>تمرین عملی</h3><p>داشبورد آموزشی با نوار کناری، کارت آمار، جدول و فرم جست‌وجو بساز؛ موبایل، صفحه‌کلید، reduced motion و forced colors را آزمایش کن.</p><h3>نکته فنی</h3><p>ویژگی‌های جدید را فقط وقتی نگه دار که در نسخه پایه نیز مسیر استفاده روشن باشد.</p><h3>معیار موفقیت</h3><p>داشبورد در موبایل و دسکتاپ، با صفحه‌کلید و تنظیمات دسترس‌پذیری کار کند.</p>","starter_code":"@layer reset,tokens,layout,components,utilities;\n@layer tokens { :root { --space:1rem; --surface:#fff; --ink:#182230; --brand:#2457a6; } }\n@layer layout { .dashboard { display:grid; grid-template-columns:16rem minmax(0,1fr); min-block-size:100dvh; } }\n@layer components { .metric { container-type:inline-size; padding:var(--space); background:var(--surface); color:var(--ink); border:1px solid #ccd3dc; border-radius:1rem; } }\n@media (max-width:48rem) { .dashboard { grid-template-columns:1fr; } }","exercise":"داشبورد آموزشی با نوار کناری، کارت آمار، جدول و فرم جست‌وجو بساز؛ موبایل، صفحه‌کلید، reduced motion و forced colors را آزمایش کن.","status":"published","sort_order":36,"estimated_minutes":45}]$lessons$::jsonb) as x(id text,course_id text,title text,slug text,summary text,content_html text,starter_code text,exercise text,status text,sort_order integer,estimated_minutes integer)
join (values
('html','html','beginner'),('html-intermediate','html','intermediate'),('html-advanced','html','advanced'),
('css','css','beginner'),('css-intermediate','css','intermediate'),('css-advanced','css','advanced'),
('javascript','javascript','beginner'),('javascript-intermediate','javascript','intermediate'),('javascript-advanced','javascript','advanced')
) as cp(course_id,language_id,level_id) on cp.course_id=x.course_id
join public.academy_courses c on c.language_id=cp.language_id and c.level_id=cp.level_id
on conflict(id) do update set title=excluded.title,slug=excluded.slug,summary=excluded.summary,content_html=excluded.content_html,starter_code=excluded.starter_code,exercise=excluded.exercise,status='published',sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,archived_at=null,updated_at=now();
commit;
